+            // calculate the current packet duration using the next block
+            double elapsed_ns = webm_track.codecDelay;
+
+            if (bloq == null) {
+                packet_flag = FLAG_LAST;// note: if the flag is FLAG_CONTINUED, is changed
+                elapsed_ns += webm_block_last_timecode;
