+    public static String stringifySeconds(double seconds) {
+        int h = (int) Math.floor(seconds / 3600);
+        int m = (int) Math.floor((seconds - (h * 3600)) / 60);
+        int s = (int) (seconds - (h * 3600) - (m * 60));
+
+        String str = "";
+
+        if (h < 1 && m < 1) {
+            str = "00:";
+        } else {
+            if (h > 0) str = pad(h) + ":";
+            if (m > 0) str += pad(m) + ":";
+        }
+
